#!/usr/bin/env python3
"""Deterministic recovery of a checkpointed transactional byte journal.

Request  : {"pages": [hex...], "checkpoint": int, "log": hex}
Response : {"pages": [hex...], "valid_bytes": int, "last_seq": int}

The journal is a sequence of records:

    payload_length:u32 | sequence:u32 | kind:u8 | transaction_id:u32 | payload | crc:u32

with ``crc == zlib.crc32(header + payload) & 0xffffffff``.  Recovery replays the
longest structurally valid prefix of the log and re-applies the transactions
that were completely and correctly sealed by a COMMIT whose sequence is newer
than the durable checkpoint watermark.
"""

import json
import struct
import sys
import zlib

# Record header: payload_length, sequence, kind, transaction_id (13 bytes).
_HEADER = struct.Struct("<IIBI")
# PATCH payload prefix: page_index, byte_offset, byte_count.
_PATCH = struct.Struct("<HHH")
# COMMIT payload: patch_count, digest.
_COMMIT = struct.Struct("<II")

_HEADER_SIZE = _HEADER.size          # 13
_CRC_SIZE = 4
_MAX_PAYLOAD = 4096

_BEGIN = 1
_PATCH_KIND = 2
_COMMIT_KIND = 3
_ABORT = 4
_VALID_KINDS = frozenset((_BEGIN, _PATCH_KIND, _COMMIT_KIND, _ABORT))


def _decode_log(log):
    """Return the raw log bytes (hex case is immaterial)."""
    if not log:
        return b""
    if isinstance(log, str):
        text = log.strip()
        if not text:
            return b""
        # Tolerate a stray "0x" prefix defensively; the contract never sends it.
        if text[:2].lower() == "0x":
            text = text[2:]
        return bytes.fromhex(text)
    if isinstance(log, (bytes, bytearray, memoryview)):
        return bytes(log)
    return b""


def _decode_pages(pages):
    decoded = []
    if isinstance(pages, (list, tuple)):
        for page in pages:
            if isinstance(page, str):
                text = page.strip()
                if text[:2].lower() == "0x":
                    text = text[2:]
                decoded.append(bytearray(bytes.fromhex(text)))
            elif isinstance(page, (bytes, bytearray)):
                decoded.append(bytearray(page))
            else:
                decoded.append(bytearray())
    return decoded


def solve(request):
    """Replay one journal request and return the recovered state."""
    if not isinstance(request, dict):
        raise TypeError("request must be an object")

    pages = _decode_pages(request.get("pages"))
    page_sizes = [len(p) for p in pages]
    log = _decode_log(request.get("log"))

    checkpoint = request.get("checkpoint", 0)
    if not isinstance(checkpoint, int) or isinstance(checkpoint, bool):
        checkpoint = int(checkpoint)

    total = len(log)
    view = memoryview(log)

    # Active incarnations: transaction_id -> list of staged PATCH payloads.
    staged = {}

    pos = 0                 # Start of the current (unvalidated) record.
    valid_bytes = 0         # Bytes in the structurally valid prefix.
    last_seq = 0            # Sequence of the last valid record.

    while pos + _HEADER_SIZE <= total:
        payload_len, seq, kind, txid = _HEADER.unpack_from(log, pos)

        # Incomplete record (header alone, or payload/CRC cut short) and
        # oversized payloads both terminate the valid prefix here.
        if payload_len > _MAX_PAYLOAD:
            break
        body_end = pos + _HEADER_SIZE + payload_len
        end = body_end + _CRC_SIZE
        if end > total:
            break

        # Sealed integrity: CRC covers the fixed header plus the payload.
        stored_crc = int.from_bytes(view[body_end:end], "little")
        if zlib.crc32(view[pos:body_end]) != stored_crc:
            break

        # Sequence must be positive and strictly increasing; the initial
        # watermark of 0 therefore also rejects a zero sequence.
        if seq <= last_seq:
            break
        if txid == 0 or kind not in _VALID_KINDS:
            break

        payload = log[pos + _HEADER_SIZE:body_end]

        # Payload shape validation (structural, independent of activity).
        if kind == _BEGIN or kind == _ABORT:
            if payload_len != 0:
                break
        elif kind == _PATCH_KIND:
            if payload_len < 7:  # 6 fixed bytes plus a positive count of data
                break
            page_index, byte_offset, byte_count = _PATCH.unpack_from(payload, 0)
            if byte_count == 0 or 6 + byte_count != payload_len:
                break
            if page_index >= len(pages):
                break
            if byte_offset + byte_count > page_sizes[page_index]:
                break
        else:  # COMMIT
            if payload_len != 8:
                break

        # The record is structurally valid: it joins the valid prefix and may
        # now take part in transaction state processing.
        valid_bytes = end
        last_seq = seq

        if kind == _BEGIN:
            # A fresh incarnation discards any unfinished one.
            staged[txid] = []
        elif kind == _PATCH_KIND:
            incarnation = staged.get(txid)
            if incarnation is not None:  # Patches for inactive IDs are ignored.
                incarnation.append(payload)
        elif kind == _ABORT:
            staged.pop(txid, None)
        else:  # COMMIT always closes the active incarnation, if any.
            incarnation = staged.pop(txid, None)
            if incarnation is not None:
                patch_count, digest = _COMMIT.unpack(payload)
                if patch_count == len(incarnation):
                    concatenation = b"".join(incarnation)
                    if zlib.crc32(concatenation) == digest and seq > checkpoint:
                        # Atomic application, in patch order.
                        for patch_payload in incarnation:
                            page_index, byte_offset, byte_count = _PATCH.unpack_from(
                                patch_payload, 0
                            )
                            pages[page_index][
                                byte_offset:byte_offset + byte_count
                            ] = patch_payload[6:6 + byte_count]
                        # Seal mismatch or a checkpointed COMMIT: incarnation is
                        # dropped without applying anything, prefix stays intact.

        pos = end

    return {
        "pages": [bytes(page).hex() for page in pages],
        "valid_bytes": valid_bytes,
        "last_seq": last_seq,
    }


def _fallback(request):
    """Best-effort response if an unexpected input shape slips through."""
    try:
        pages = list(request.get("pages", []))
    except Exception:
        pages = []
    return {"pages": pages, "valid_bytes": 0, "last_seq": 0}


def main(stream=None, out=None):
    out = sys.stdout if out is None else out
    stream = sys.stdin if stream is None else stream
    for line in stream:
        if not line.strip():
            continue
        try:
            response = solve(json.loads(line))
        except Exception as exc:  # pragma: no cover - defensive only
            print("recovery error: %r" % (exc,), file=sys.stderr)
            try:
                response = _fallback(json.loads(line))
            except Exception:
                response = {"pages": [], "valid_bytes": 0, "last_seq": 0}
        out.write(json.dumps(response))
        out.write("\n")
    try:
        out.flush()
    except Exception:
        pass


if __name__ == "__main__":
    main()
